// Shared by the pi extension and the opencode v2 plugin; config.json is generated by hmModules/ai/proxy.nix.
import { readFileSync } from "node:fs";

export const config = JSON.parse(readFileSync(new URL("./config.json", import.meta.url), "utf8"));

export const DEFAULT_CONTEXT = 200_000;
export const DEFAULT_OUTPUT = 32_000;
const DEFAULT_EFFORTS = ["low", "medium", "high"];
const OWNER_GROUPS = { "opencode-zen-free": "opencode" };

export function apiKey() {
  return config.keyFile ? readFileSync(config.keyFile, "utf8").trim() : "none";
}

// Aliases carry their target's display name, so match that too.
function apiOf(id, displayName) {
  if (/^claude/i.test(id) || /^claude/i.test(displayName ?? "")) return "anthropic";
  if (/^gemini/i.test(id)) return "gemini";
  return "openai";
}

async function get(path) {
  const res = await fetch(`${config.baseUrl}${path}`, {
    headers: { authorization: `Bearer ${apiKey()}` },
    signal: AbortSignal.timeout(5_000),
  });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return res.json();
}

// The codex-format catalog adds context windows, modalities and reasoning levels to /v1/models,
// but drops its owner. Both list only models with an account available right now.
async function fetchCatalog() {
  const [{ models }, { data }] = await Promise.all([get("/v1/models?client_version=1"), get("/v1/models")]);
  const owners = new Map(data.map((m) => [m.id, m.owned_by]));
  return (
    models
      // Display-name aliases ("Claude Opus 5.5") duplicate their slug; image models cannot chat.
      .filter((m) => !/\s/.test(m.slug) && !/(^|-)image(-|$)/.test(m.slug))
      .map((m) => ({
        id: m.slug,
        api: apiOf(m.slug, m.display_name),
        owner: owners.get(m.slug),
        name: m.display_name || m.slug,
        contextWindow: m.context_window ?? undefined,
        maxOutput: m.max_output_tokens ?? undefined,
        efforts: (m.supported_reasoning_levels ?? []).map((l) => l.effort),
        image: (m.input_modalities ?? []).includes("image"),
      }))
  );
}

/**
 * The catalog with `config.models` laid over it, grouped into providers: one per API, except that
 * Responses models from someone other than OpenAI get one per owner. Falls back to `config.models` alone.
 */
export async function discover(warn = console.warn) {
  let found = [];
  try {
    found = await fetchCatalog();
  } catch (error) {
    warn(`[${config.name}] model discovery failed, using only the configured models: ${error.message}`);
  }
  const byId = new Map(found.map((m) => [m.id, m]));
  for (const [id, { reasoning, ...override }] of Object.entries(config.models)) {
    const model = { id, name: id, efforts: [], image: false, ...byId.get(id), ...override };
    if (reasoning === false) model.efforts = [];
    if (reasoning === true && model.efforts.length === 0) model.efforts = DEFAULT_EFFORTS;
    byId.set(id, model);
  }
  const groups = {};
  for (const model of byId.values()) {
    const owner = OWNER_GROUPS[model.owner] ?? model.owner;
    const group = model.api === "openai" && owner && owner !== "openai" ? owner : model.api;
    (groups[group] ??= { api: model.api, models: [] }).models.push(model);
  }
  return groups;
}

/** A harness's provider config for `group`: its API's, renamed for an owner group. */
export function providerFor(providers, group, api) {
  if (group === api) return providers[api];
  return { ...providers[api], id: `${config.name}-${group}`, name: `${config.label} (${group})` };
}
